import test from 'node:test';
import assert from 'node:assert/strict';
import { assessAllowedRequest, assessCleanup, assessObservation, assessPreSubmit, isConnectionRefused, validateContract } from './probe.mjs';

const contract = {schema_version:'static-content-local-v1',budgets:{decoded_bytes:131072,response_end_ms:100,dom_content_loaded_ms:250,load_end_ms:500},lanes:[{width:390,height:1000,theme:'light'},{width:390,height:1000,theme:'dark'},{width:1440,height:1000,theme:'light'},{width:1440,height:1000,theme:'dark'}],javascript:false,cache:'disabled',network:'unthrottled-owned-loopback',assets:['/static/app.css'],paths:['/content','/content/choosing-a-profile','/content/not-a-page']};
const css = {sha256:'abc',bytes:10};
const good = {origin:'http://127.0.0.1:1',url:'http://127.0.0.1:1/content',status:200,expectedStatus:200,html:{bytes:100,sha256:'x'},taskPassed:true,scriptNodes:0,scriptAttempts:0,deniedRequests:[],resources:[{url:'http://127.0.0.1:1/content',method:'GET',kind:'document',status:200,fromCache:false,terminal:true,bodyAvailable:true,decodedBytes:100,sha256:'x'},{url:'http://127.0.0.1:1/static/app.css',method:'GET',kind:'stylesheet',status:200,fromCache:false,terminal:true,bodyAvailable:true,decodedBytes:10,sha256:'abc'}],timings:{responseEnd:10,domContentLoaded:20,loadEnd:30}};

test('contract accepts only the pinned shape',()=>{ assert.deepEqual(validateContract(structuredClone(contract)),contract); assert.throws(()=>validateContract({...contract,javascript:true})); assert.throws(()=>validateContract({...contract,budgets:{...contract.budgets,load_end_ms:NaN}})); const duplicate=structuredClone(contract);duplicate.lanes[3]=duplicate.lanes[0];assert.throws(()=>validateContract(duplicate)); });
test('request allowlist is exact and fail closed',()=>{ assert.deepEqual(assessAllowedRequest('http://127.0.0.1:1','http://127.0.0.1:1/content?theme=dark&state=empty'),[]); assert.ok(assessAllowedRequest('http://127.0.0.1:1','https://evil.test/content').length); assert.ok(assessAllowedRequest('http://127.0.0.1:1','http://127.0.0.1:1/static/app.css?x=1').length); });
test('valid observation passes',()=>assert.deepEqual(assessObservation(contract,good,css),[]));
test('status and css mismatch fail',()=>{ const x=structuredClone(good); x.status=503; x.resources[1].sha256='bad'; assert.deepEqual(assessObservation(contract,x,css).sort(),['css.identity','status']); });
test('document css and cache evidence are mandatory',()=>{ const noDoc=structuredClone(good);noDoc.resources.shift();assert.ok(assessObservation(contract,noDoc,css).includes('document.identity')); const cssStatus=structuredClone(good);cssStatus.resources[1].status=404;assert.ok(assessObservation(contract,cssStatus,css).includes('css.identity')); const cached=structuredClone(good);cached.resources[0].fromCache=true;assert.ok(assessObservation(contract,cached,css).includes('resource.cache')); });
test('retained HTML must equal delivered document body',()=>{ const x=structuredClone(good);x.html.sha256='different';assert.ok(assessObservation(contract,x,css).includes('document.artifact')); });
test('invalid resource URL fails closed',()=>{ const x=structuredClone(good);x.resources[0].url='%%%';assert.ok(assessObservation(contract,x,css).includes('resource.url')); });
test('blocked network and absent task facts fail',()=>{ const x={...good,taskPassed:false,deniedRequests:['x']}; const f=assessObservation(contract,x,css); assert.ok(f.includes('task')&&f.includes('network')); });
test('scripts fail',()=>assert.ok(assessObservation(contract,{...good,scriptNodes:1},css).includes('script-free')));
test('missing body and terminal state fail',()=>{ const x=structuredClone(good); x.resources[0].bodyAvailable=false; x.resources[0].terminal=false; const f=assessObservation(contract,x,css); assert.ok(f.includes('resource.body')&&f.includes('resource.terminal')); });
test('over budget fails',()=>{ const x=structuredClone(good); x.resources[0].decodedBytes=131072; assert.ok(assessObservation(contract,x,css).includes('budget.bytes')); });
test('missing NaN and reversed timings fail',()=>{ for (const value of [undefined,NaN]) { const x=structuredClone(good); x.timings.loadEnd=value; assert.ok(assessObservation(contract,x,css).includes('timing.loadEnd')); } const x=structuredClone(good); x.timings.responseEnd=30;x.timings.domContentLoaded=20; assert.ok(assessObservation(contract,x,css).includes('timing.order')); });
test('cleanup must prove both processes and refused listener',()=>{ assert.deepEqual(assessCleanup({browser:{exitCode:0,signalCode:null},gallery:{exitCode:0,signalCode:null},portRefused:true}),[]); assert.ok(assessCleanup({}).length===3); });
test('only ECONNREFUSED proves listener refusal',()=>{ assert.equal(isConnectionRefused({code:'ECONNREFUSED'}),true); assert.equal(isConnectionRefused({code:'ETIMEDOUT'}),false); assert.equal(isConnectionRefused(undefined),false); });
test('missing pre-submit navigation evidence fails closed',()=>{
  const fact={selected:'empty',activeMatchesSubmit:true,url:'http://127.0.0.1/content?theme=light'};
  assert.deepEqual(assessPreSubmit(fact,'empty',fact.url),['pre-submit.navigation']);
});
test('native selection must be exact and remain pre-submit',()=>{ const fact={selected:'empty',activeMatchesSubmit:true,url:'http://127.0.0.1/content?theme=light',navigationObserved:false}; assert.deepEqual(assessPreSubmit(fact,'empty',fact.url),[]); assert.ok(assessPreSubmit({...fact,selected:'ready'},'empty',fact.url).includes('pre-submit.value')); assert.ok(assessPreSubmit({...fact,activeMatchesSubmit:false},'empty',fact.url).includes('pre-submit.focus')); assert.ok(assessPreSubmit({...fact,navigationObserved:true},'empty',fact.url).includes('pre-submit.navigation')); assert.ok(assessPreSubmit({...fact,url:fact.url},'empty',fact.url+'#same-url-navigation').includes('pre-submit.navigation')); });
